schema_ddl:
CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ragione_sociale TEXT NOT NULL,
    partita_iva TEXT UNIQUE NOT NULL
);

CREATE TABLE categorie_prodotto (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome_categoria TEXT NOT NULL
);

CREATE TABLE prodotti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    categoria_id INT NOT NULL REFERENCES categorie_prodotto(id) ON DELETE RESTRICT,
    nome TEXT NOT NULL,
    prezzo NUMERIC(10,2) CHECK (prezzo >= 0)
);

CREATE TABLE ordini_cliente (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id) ON DELETE CASCADE,
    data_ordine DATE NOT NULL DEFAULT CURRENT_DATE,
    stato_evasione TEXT NOT NULL CHECK (stato_evasione IN ('attesa', 'completato', 'annullato'))
);

CREATE TABLE dettagli_ordine (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ordine_id INT NOT NULL REFERENCES ordini_cliente(id) ON DELETE CASCADE,
    prodotto_id INT NOT NULL REFERENCES prodotti(id) ON DELETE RESTRICT,
    quantita INT NOT NULL CHECK (quantita > 0)
);
